public interface IShape
{
    double Area();
    void Draw();
}

public interface IPaymentProcessor
{
    void ProcessPayment(decimal amount);
    bool Refund(string transactionId);
}

public class StripeProcessor : IPaymentProcessor
{
    public void ProcessPayment(decimal amount)
    {
        Console.WriteLine($"Charged {amount}");
    }

    public bool Refund(string transactionId)
    {
        return true;
    }
}

public class SmartDevice : IConnectable, IUpdatable, ITrackable
{
    public void Connect() { }
    public void Update() { }
    public void Track() { }
}

public interface ILogger
{
    string Name { get; set; }
    event Action<string> OnMessageLogged;
}

// Interface - unrelated types
public interface IFlyable { void Fly(); }
public class Bird : IFlyable { }
public class Airplane : IFlyable { }

// Abstract class - related types
public abstract class Animal { public abstract void Speak(); }

public interface ILogger { void Log(string msg); }
public class DualLogger : ILogger
{
    void ILogger.Log(string msg) => Console.WriteLine(msg);
}

